final desktopSelectedAddressId = StateProvider.autoDispose<Id?>((ref) => null);

class DesktopWalletAddressesView extends ConsumerStatefulWidget {
  const DesktopWalletAddressesView({super.key, required this.walletId});

  static const String routeName = "/desktopWalletAddressesView";

  final String walletId;

  @override
  ConsumerState<DesktopWalletAddressesView> createState() =>
      _DesktopWalletAddressesViewState();
}

class _DesktopWalletAddressesViewState
    extends ConsumerState<DesktopWalletAddressesView> {
  static const _headerHeight = 70.0;
  static const _columnWidth0 = 489.0;

  Stream<void>? addressCollectionWatcher;

  void _onAddressCollectionWatcherEvent() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        setState(() {});
      }
    });
  }

  @override
  void initState() {
    addressCollectionWatcher = ref
        .read(mainDBProvider)
        .isar
        .addresses
        .watchLazy(fireImmediately: true);
    addressCollectionWatcher!.listen((_) => _onAddressCollectionWatcherEvent());

    super.initState();
  }

  @override
  void dispose() {
    addressCollectionWatcher = null;
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final wallet = ref.watch(
      pWallets.select((value) => value.getWallet(widget.walletId)),
    );

    final bool canGen;
    if (wallet is ViewOnlyOptionInterface &&
        wallet.isViewOnly &&
        // Neither type carries an xpub, so no further address can be derived.
        (wallet.viewOnlyType == ViewOnlyWalletType.addressOnly ||
            wallet.viewOnlyType == ViewOnlyWalletType.spark)) {
      canGen = false;
    } else {
      canGen = wallet is MultiAddressInterface;
    }

    return DesktopScaffold(
      appBar: DesktopAppBar(
        background: Theme.of(context).extension<StackColors>()!.popupBG,
        leading: Expanded(
          child: Row(
            children: [
              const SizedBox(width: 32),
              AppBarIconButton(
                size: 32,
                color: Theme.of(
                  context,
                ).extension<StackColors>()!.textFieldDefaultBG,
                shadows: const [],
                icon: SvgPicture.asset(
                  Assets.svg.arrowLeft,
                  width: 18,
                  height: 18,
                  color: Theme.of(
                    context,
                  ).extension<StackColors>()!.topNavIconPrimary,
                ),
                onPressed: Navigator.of(context).pop,
              ),
              const SizedBox(width: 12),
              Text("Address list", style: STextStyles.desktopH3(context)),
              const Spacer(),
              if (canGen)
                SizedBox(
                  width: 200,
                  child: GenerateAddressButton(
                    buttonHeight: ButtonHeight.l,
                    generateAddress: (wallet as MultiAddressInterface)
                        .generateNewReceivingAddress,
                  ),
                ),
              const SizedBox(width: 32),
            ],
          ),
        ),
        useSpacers: false,
        isCompactHeight: true,
      ),
      body: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(
          children: [
            Expanded(
              child: Row(
                children: [
                  SizedBox(
                    width: _columnWidth0,
                    child: DesktopAddressList(
                      searchHeight: _headerHeight,
                      walletId: widget.walletId,
                    ),
                  ),
                  const SizedBox(width: 16),
                  Expanded(
                    child: Column(
                      children: [
                        const SizedBox(height: _headerHeight),
                        if (ref.watch(desktopSelectedAddressId.state).state !=
                            null)
                          Expanded(
                            child: SingleChildScrollView(
                              child: AddressDetailsView(
                                key: Key(
                                  "currentDesktopAddressDetails_key_${ref.watch(desktopSelectedAddressId.state).state}",
                                ),
                                walletId: widget.walletId,
                                addressId: ref
                                    .watch(desktopSelectedAddressId.state)
                                    .state!,
                              ),
                            ),
                          ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
